def prime_factors(n: int) -> list:
    if not isinstance(n, int) or not isinstance(n, int) or n <= 1:
        raise ValueError("Input must be a positive integer greater than 1")
    if n == 1:
        return []
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return sorted(list(factors))
